arguments.command:
cat > /tmp/askpass.sh <<'EOF'
#!/bin/sh
case "$1" in
  *[Uu]sername*) echo "x-access-token" ;;
  *) printf '%s\n' "$GITHUB_TOKEN" ;;
esac
EOF
chmod +x /tmp/askpass.sh
cd /tmp/phoebe-wt && git config user.name; git config user.email; GIT_ASKPASS=/tmp/askpass.sh GIT_TERMINAL_PROMPT=0 git push origin HEAD:refs/heads/friend/phoebe 2>&1 | tail -5
